text:
{
  "design": {
    "theme": "splash",
    "picture_style": "photo"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall familiar animal names",
      "look_at": {
        "kind": "picture",
        "shows": "Four familiar adult animals"
      },
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Share the learning objectives",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Predict which animals belong together",
      "look_at": {
        "kind": "picture",
        "shows": "A cow, a calf and a puppy"
      },
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Model naming an adult and its young",
      "look_at": {
        "kind": "picture",
        "shows": "A cow beside its calf"
      },
      "teaches": [1]
    },
    {
      "slide": 5,
      "does": "Try the same adult–young match",
      "look_at": {
        "kind": "picture",
        "shows": "A different cow, calf and puppy"
      },
      "teaches": [1]
    },
    {
      "slide": 6,
      "does": "Teach the other three pairs",
      "look_at": {
        "kind": "picture",
        "shows": "Sheep and lamb, hen and chick, dog and puppy"
      },
      "teaches": [1]
    },
    {
      "slide": 7,
      "does": "Check all four adult–young names",
      "look_at": {
        "kind": "picture",
        "shows": "Four adult animals and their young in mixed positions"
      },
      "teaches": [1]
    },
    {
      "slide": 8,
      "does": "Explain how a chick grows",
      "look_at": {
        "kind": "picture-sequence",
        "shows": "A female chick becoming bigger and developing adult feathers"
      },
      "teaches": [2]
    },
    {
      "slide": 9,
      "does": "Describe the same growth changes",
      "look_at": {
        "kind": "picture",
        "shows": "A small chick and a fully grown hen"
      },
      "teaches": [2]
    },
    {
      "slide": 10,
      "does": "Correct the idea that growth is only getting bigger",
      "look_at": {
        "kind": "picture",
        "shows": "Fluffy chick down compared with adult hen feathers"
      },
      "teaches": [2]
    },
    {
      "slide": 11,
      "does": "Check understanding of chick growth",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [2]
    },
    {
      "slide": 12,
      "does": "Apply both ideas to new animal-care situations",
      "look_at": {
        "kind": "picture",
        "shows": "A chick and a lamb in separate farm pens"
      },
      "teaches": [1, 2]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Animals and their young",
    "lead": "Name the animals you know.",
    "picture": {
      "shows": "Four separate photographs of familiar adult farm and pet animals",
      "must_see": [
        "adult cow",
        "adult sheep",
        "adult hen",
        "adult dog"
      ],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "question-set",
      "heading": "Which young animal?",
      "questions": [
        "Which young animal goes with the cow?",
        "What do you think it is called?"
      ],
      "instruction": "Point and say.",
      "picture": {
        "shows": "An adult cow above two separate photographs of a calf and a puppy, with no pairing shown",
        "must_see": [
          "adult cow",
          "young calf",
          "young puppy"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "visual-text",
      "heading": "Cow and calf",
      "lead": "A calf is a young cow.",
      "points": [
        {
          "label": "Say it",
          "text": "Cow and calf."
        }
      ],
      "figure": {
        "shows": "An adult cow standing beside its small calf",
        "must_see": [
          "large adult cow",
          "small young calf",
          "similar body shapes"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "question-set",
      "heading": "Try it",
      "questions": [
        "Which young animal goes with the cow?",
        "Name the adult and its young."
      ],
      "instruction": "Point and say.",
      "picture": {
        "shows": "A different adult cow above separate photographs of a puppy and a calf, reversing the earlier choice positions",
        "must_see": [
          "adult brown cow",
          "young puppy",
          "young brown calf"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "compare",
      "heading": "Meet three more pairs",
      "columns": [
        {
          "label": "Sheep and lamb",
          "text": "A lamb is a young sheep.",
          "picture": {
            "shows": "An adult sheep beside a small lamb",
            "must_see": [
              "adult woolly sheep",
              "small young lamb"
            ],
            "subject": "generic"
          }
        },
        {
          "label": "Hen and chick",
          "text": "A chick is a young chicken.",
          "picture": {
            "shows": "An adult hen beside a small chick",
            "must_see": [
              "adult feathered hen",
              "small fluffy chick"
            ],
            "subject": "generic"
          }
        },
        {
          "label": "Dog and puppy",
          "text": "A puppy is a young dog.",
          "picture": {
            "shows": "An adult dog beside a small puppy",
            "must_see": [
              "adult dog",
              "small young puppy"
            ],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "practice",
      "heading": "Find the pairs",
      "questions": [
        "Find the cow’s young. Name both.",
        "Find the sheep’s young. Name both.",
        "Find the hen’s and dog’s young. Name each pair."
      ],
      "instruction": "Match and say.",
      "picture": {
        "shows": "Eight separate animal photographs in two rows: cow, sheep, hen and dog above; puppy, chick, calf and lamb below, with no connecting lines",
        "must_see": [
          "adult cow",
          "adult sheep",
          "adult hen",
          "adult dog puppies absent"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "picture-sequence",
      "heading": "A chick grows into a hen",
      "sequence": [
        {
          "shows": "A newly hatched female chick covered in fluffy down, with no adult wing or tail feathers yet",
          "must_see": [
            "small fluffy chick",
            "short tiny wings"
          ],
          "subject": "generic",
          "caption": "Small and fluffy"
        },
        {
          "shows": "A larger young female chicken with developing wing feathers but without the full adult plumage of the next stage",
          "must_see": [
            "larger young chicken",
            "growing wing feathers",
            "some fluffy down"
          ],
          "subject": "generic",
          "caption": "Bigger; feathers grow"
        },
        {
          "shows": "A fully grown hen with adult body, wing and tail feathers",
          "must_see": [
            "fully grown hen",
            "adult wing feathers",
            "adult tail feathers"
          ],
          "subject": "generic",
          "caption": "Hen: adult feathers"
        }
      ]
    },
    {
      "template": "question-set",
      "heading": "Tell the changes",
      "questions": [
        "Name the young animal and the adult.",
        "How has its size changed?",
        "How has its covering changed?"
      ],
      "instruction": "Look closely. Say what changed.",
      "picture": {
        "shows": "A small fluffy female chick and a fully grown hen photographed side by side at the same scale",
        "must_see": [
          "small fluffy chick",
          "much larger hen",
          "long adult feathers"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "compare",
      "heading": "More than getting bigger",
      "columns": [
        {
          "label": "Chick",
          "text": "Soft, fluffy down",
          "picture": {
            "shows": "A close view of the fluffy down covering a newly hatched chick",
            "must_see": [
              "soft fluffy down",
              "small chick wing"
            ],
            "subject": "generic"
          }
        },
        {
          "label": "Hen",
          "text": "Adult feathers have grown.",
          "picture": {
            "shows": "A close view of a hen's overlapping adult wing and tail feathers",
            "must_see": [
              "long wing feathers",
              "adult tail feathers"
            ],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "hinge",
      "heading": "Choose the best answer",
      "stem": "How does a chick change as it grows into a hen?",
      "options": [
        "It only gets bigger.",
        "It gets bigger and grows adult feathers.",
        "It stays small and grows fur."
      ],
      "correct": 2
    },
    {
      "template": "question-set",
      "heading": "Help on the farm",
      "questions": [
        "The lamb needs its mum. Which animal will you find?",
        "This female chick grows up. What will it become?",
        "Draw how the chick will look when fully grown."
      ],
      "instruction": "Say your ideas. Then draw.",
      "picture": {
        "shows": "A small fluffy female chick and a young lamb in separate farm pens, with no adult animals visible",
        "must_see": [
          "small fluffy chick",
          "small young lamb",
          "separate farm pens"
        ],
        "subject": "generic"
      }
    }
  ]
}
